tests.script:
on Echo(name, tags, stats, maybe, flag, percent, heading, position, point, category, points, span) {
  publish Echoed(name: name, tags: tags, stats: stats, maybe: maybe, flag: flag, percent: percent, heading: heading, position: position, point: point, category: category, points: points, span: span)
}

record :gauge as {
  current: :decimal clamped between 0 and maximum,
  maximum: :decimal clamped between 0 and :infinity,
  percentage: :percentage computed by
    0% when maximum <= 0,
    otherwise (current / maximum) as :percentage
}

on Start {
  let hp as :gauge be [current: 125, maximum: 100]
  publish Done(meter: hp, isMeter: hp is :gauge)
}

on Start {
  let heading be :degree(180)
  let distance be :meter(100)
  let duration be :second(15)
  let product be :decimal(90°) * :decimal(100m)
  let ratio be :percentage(25)
  let textValue be :text(heading)
  publish Done(heading: heading, distance: distance, duration: duration, product: product, ratio: ratio, textValue: textValue, headingIsDegree: heading is :degree)
}

on Start {
  let position be :vector2(10.5, -2)
  let labeledPosition be :vector2(x: 3, y: 4)
  let yOnly be :vector2(y: 10m)
  let zero2 be :vector2()
  let point be :vector3(1, 2, 3)
  let labeledPoint be :vector3(x: 4, y: 5, z: 6)
  let zOnly be :vector3(z: 7m)
  let yzOnly be :vector3(y: 2m, z: 3m)
  let zero3 be :vector3()
  let lifted be :vector3(position)
  let liftedWithZ be :vector3(position, 7)
  let flattened be :vector2(labeledPoint)
  publish Done(position: position, labeledPosition: labeledPosition, yOnly: yOnly, zero2: zero2, point: point, labeledPoint: labeledPoint, zOnly: zOnly, yzOnly: yzOnly, zero3: zero3, lifted: lifted, liftedWithZ: liftedWithZ, flattened: flattened, x: position.x, y: labeledPosition.y, z: point.z, labeledX: labeledPoint.x)
}

record :gauge as {
  current: :decimal clamped between 0 and maximum,
  maximum: :decimal clamped between 0 and :infinity,
  percentage: :percentage computed by
    0% when maximum <= 0,
    otherwise (current / maximum) as :percentage
}

on Start {
  let hp be :gauge(current: 125, maximum: 100)
  publish Done(meter: hp, current: hp.current, percentage: hp.percentage, isMeter: hp is :gauge)
}

on Start {
  let origin be :point2(10m, 20m)
  let delta be :vector2(3m, -5m)
  let moved be origin + delta
  let back be moved - delta
  let between be moved - origin
  let labeled be :point2(x: 3, y: 4)
  let yOnly be :point2(y: 10m)
  let zero2 be :point2()
  let p3 be :point3(origin, 7m)
  let flat be :point2(p3)
  let badAdd be origin + moved
  let badScale be origin * 2
  let badAbs be :abs origin
  publish Done(origin: origin, moved: moved, back: back, between: between, labeled: labeled, yOnly: yOnly, zero2: zero2, p3: p3, flat: flat, x: moved.x, z: p3.z, isPoint: moved is :point2, badAdd: badAdd, badScale: badScale, badAbs: badAbs)
}

on Start {
  publish Done(add: 1 + 2, subtract: 5 - 3, multiply: 6 * 7, modulo: 7 mod 4, divide: 7 / 2, mixed: 7 * 0.5)
}

on Start(a, b) {
  publish Done(divPositive: a div b, divNegative: (0 - a) div b, divNegativeDivisor: a div (0 - b), decimalDiv: 7.5 div 2, sameUnitDiv: 7m div 2m, unitDivScalar: 7m div 2, modPositive: a mod b, modNegative: (0 - a) mod b, modNegativeDivisor: a mod (0 - b), remPositive: a rem b, remNegative: (0 - a) rem b, remNegativeDivisor: a rem (0 - b), divZero: a div 0, remZero: a rem 0)
}

on Start {
  publish Done(addToBase: 100 + 5%, subtractFromBase: 100 - 5%, multiplyBaseRight: 100 * 5%, divideBaseByPercent: 100 / 5%, reverseAdd: 5% + 100, reverseSubtract: 5% - 100, percentAdd: 15% + 15%, percentSubtract: 15% - 5%, percentScaleRight: 15% * 2, percentDivideScalar: 15% / 3, scalarScaleLeft: 2 * 15%, percentProduct: 15% * 15%, percentRatio: 15% / 15%, percentDivideZero: 15% / 0)
}

on Start {
