on Start {
  let castMeter as :meter be 100
  let rawMeter as :decimal be castMeter
  publish Done(distance: 100m, duration: 15s, castMeter: castMeter, rawMeter: rawMeter, isMeter: castMeter is :meter, isSecond: 15s is :second, isDecimal: castMeter is :decimal, sameAdd: 100m + 50m, mixedAdd: 100m + 50, wrongAdd: 100m + 5s, scaleLeft: 100m * 2, scaleRight: 2 * 100m, divideScalar: 100m / 2, divideSame: 100m / 25m, unitModulo: 370m mod 90m, unitModuloScalar: 100m mod 3, wrapMeter: :degree.wrap 10m)
}

on Start(value, heading, unitlessHeading, meterValue) {
  let pi be :degree.toRadians 180°
  publish Done(floorBare: :integer.floor value, floorCall: :integer.floor(value), floorNegative: :integer.floor -10.4, ceilNegative: :integer.ceil -10.4, truncateNegative: :integer.truncate -10.4, halfEven12: :integer.halfEven 12.5, halfEven13: :integer.halfEven 13.5, halfUpNegative: :integer.halfUp -12.5, halfDownNegative: :integer.halfDown -12.5, wrapNegative: :degree.wrap heading, wrapUnitless: :degree.wrap unitlessHeading, radians: pi, degrees: :degree.fromRadians pi, wrapWrongUnit: :degree.wrap meterValue, radiansWrongUnit: :degree.toRadians meterValue, fromRadiansWrongUnit: :degree.fromRadians meterValue)
}

on Start {
  let position be :vector2(3m, 4m)
  let rawPosition be :decimal(position)
  let rawPositionCast as :decimal be position
  let remetered be :meter(rawPosition)
  let sameMeter be :meter(position)
  let wrongUnitVector be :second(position)
  let wrongScalarUnit be :meter(15s)
  let lifted as :vector3 be position
  let liftedConstructed be :vector3(position)
  let liftedConstructedWithZ be :vector3(position, 20m)
  let flattened as :vector2 be :vector3(1m, 2m, 3m)
  let flattenedConstructed be :vector2(:vector3(1m, 2m, 3m))
  let vectorList as :list be position
  let vectorDictionary as :dictionary be position
  publish Done(position: position, x: position.x, y: position[:y], listY: vectorList[2], dictX: vectorDictionary.x, rawPosition: rawPosition, rawPositionCast: rawPositionCast, remetered: remetered, sameMeter: sameMeter, wrongUnitVector: wrongUnitVector, wrongScalarUnit: wrongScalarUnit, lifted: lifted, liftedConstructed: liftedConstructed, liftedConstructedWithZ: liftedConstructedWithZ, flattened: flattened, flattenedConstructed: flattenedConstructed)
}

on Start {
  let a be :vector2(1m, 2m)
  let b be :vector2(3m, 4m)
  let c be :vector3(1, 2, 2)
  publish Done(sum: a + b, difference: a - b, negated: -a, scaleRight: a * 2, scaleLeft: 2 * a, percentScale: a * 50%, divided: b / 2, unitlessScaled: :vector2(1, 2) * 5m, unitDivided: a / 1m, length2: :abs :vector2(3m, 4m), length3: :abs c)
}

on Start {
  publish Done(mixedUnits: :vector2(10m, 20s), mixedUnitless: :vector2(10, 20m), partialMixedUnit: :vector3(y: 20m, z: 30), liftedMixedUnit: :vector3(:vector2(10m, 20m), 20), vectorProduct: :vector2(1, 2) * :vector2(3, 4), scalarDivide: 10 / :vector2(1, 2), dimensionAdd: :vector2(1, 2) + :vector3(1, 2, 3), incompatibleScalar: :vector2(1m, 2m) * 5s, divideZero: :vector2(1, 2) / 0, vectorModulo: :vector2(1, 2) mod 2)
}

on Start(opt, missingValue) {
  let text be 'Hello ''World'', I''m here'
  let myList be [1, 2, 3]
  let myValues be [name: 'Hello', position: 1]
  let emptyValues be [:]
  let distance be :abs (0 - 12.5)
  let boundedHigh be :clamp 120 between 0 and 99
  let boundedLow be :clamp (0 - 3) between 0 and 99
  let highest be :max of 4 and 9 and 2;
  let lowest be :min of 4 and 9 and 2;
  publish Done(text: text, listLen: :len myList, name: myValues.name, position: myValues.position, emptyLen: :len emptyValues, distance: distance, boundedHigh: boundedHigh, boundedLow: boundedLow, highest: highest, lowest: lowest, optionalFallback: opt :default 10, nothingFallback: missingValue :default 20)
}

on Start(d6) {
  let kept be d6
  publish Done(value: kept)
}

on Start {
  let values be [3, 1, 2, 2]
  publish Done(textContains: 'club' in 'battle club', startsList: [1, 2, 3] starts with [1, 2], endsList: [1, 2, 3] ends with [1, 2], hasAll: [1, 2, 3][:contains all [1, 3]], hasAny: [1, 2, 3][:contains any [0, 3]], sorted: values[:sort ascending], distinct: values[:distinct])
}

on Start(entry, keyName) {
  let values be [10, 20, 30]
  let tags be :set['alpha', 'beta']
  let lookupProperty be :name
  publish Done(first: values[1], third: values[3], zero: values[0], missingIndex: values[4], property: entry.name, textKey: entry['name'], tagKey: entry[:name], dynamicTag: entry[lookupProperty], dynamicText: entry[keyName], missingProperty: entry['missing'], firstTag: tags[1], missingTag: tags[3])
}

on Start(opt, emptyText, emptyList, emptyDict, zeroValue, falseValue, diceValue, nanValue, infinityValue) {
  publish Done(hasOpt: has value opt, hasEmptyText: has value emptyText, hasEmptyList: has value emptyList, hasEmptyDict: has value emptyDict, hasZero: has value zeroValue, hasFalse: has value falseValue, hasNaN: has value nanValue, hasInfinity: has value infinityValue, isEmptyOpt: empty opt, isEmptyText: empty emptyText, isEmptyList: empty emptyList, isEmptyDict: empty emptyDict, isEmptyDice: empty diceValue, isEmptyNaN: empty nanValue, isEmptyInfinity: empty infinityValue, notEmptyList: not empty [1], notFalse: not falseValue, optValue: opt :default 10, listValue: (emptyList :default [1, 2])[1], textValue: emptyText :default 'fallback', dictValue: (emptyDict :default [name: 'default']).name, missingTextValue: emptyDict['name'] :default 'fallback')
}

on Start {
  publish Done(wordTrue: true xor false, wordFalse: true xor true, symbolTrue: true ^ false, symbolFalse: false ^ false)
}
